<?php
declare(strict_types=1);
function payroll_run_schema(): PDO {
 $db=payroll_schema();$cols=array_column($db->query('PRAGMA table_info(payroll_runs)')->fetchAll(),'name');foreach(['run_kind'=>"TEXT NOT NULL DEFAULT 'manual'",'pay_date'=>"TEXT NOT NULL DEFAULT ''",'note_count'=>'INTEGER NOT NULL DEFAULT 0'] as $col=>$type)if(!in_array($col,$cols,true))$db->exec('ALTER TABLE payroll_runs ADD COLUMN '.$col.' '.$type);
 $db->exec("CREATE UNIQUE INDEX IF NOT EXISTS payroll_automatic_month ON payroll_runs(month) WHERE run_kind='automatic';CREATE TABLE IF NOT EXISTS payroll_notes(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,month TEXT NOT NULL,recurring INTEGER NOT NULL DEFAULT 0,amount INTEGER NOT NULL DEFAULT 0,note TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,actor TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS payroll_notes_user ON payroll_notes(user_id,month)");return $db;
}
function payroll_pay_date(string $month): string {people_month($month);return (new DateTimeImmutable($month.'-01',new DateTimeZone('Asia/Ho_Chi_Minh')))->modify('+1 month')->format('Y-m').'-20';}
function payroll_due_month(?DateTimeImmutable $now=null): ?string {$now??=new DateTimeImmutable('now',new DateTimeZone('Asia/Ho_Chi_Minh'));$now=$now->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'));return $now->format('d')==='20'?$now->modify('first day of last month')->format('Y-m'):null;}
function payroll_note_save(array $data): void {
 people_require_owner();$db=payroll_run_schema();$id=$data['id']??0;$uid=$data['user_id']??0;$month=$data['month']??'';people_month($month);$amount=$data['amount']??0;$note=trim((string)($data['note']??''));$recurring=$data['recurring']??false;$active=$data['active']??true;if(!is_int($id)||!is_int($uid)||$id<0||$uid<1||!is_int($amount)||$amount<0||$amount>100000000||mb_strlen($note)<3||mb_strlen($note)>2000||!is_bool($recurring)||!is_bool($active))throw new RuntimeException('Cần nhân viên, tháng công, ghi chú và số tiền cộng thêm hợp lệ (có thể bằng 0 để chỉ nhắc việc).',400);
 $q=$db->prepare('SELECT 1 FROM staff WHERE id=?');$q->execute([$uid]);if(!$q->fetchColumn())throw new RuntimeException('Không tìm thấy nhân viên.',404);$old=null;if($id){$q=$db->prepare('SELECT * FROM payroll_notes WHERE id=?');$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('Không tìm thấy ghi chú.',404);}
 $db->beginTransaction();try{$args=[$uid,$month,$recurring?1:0,$amount,$note,$active?1:0,team_identity()['username'],gmdate('c')];if($id){$args[]=$id;$db->prepare('UPDATE payroll_notes SET user_id=?,month=?,recurring=?,amount=?,note=?,active=?,actor=?,updated_at=? WHERE id=?')->execute($args);}else $db->prepare('INSERT INTO payroll_notes(user_id,month,recurring,amount,note,active,actor,updated_at) VALUES(?,?,?,?,?,?,?,?)')->execute($args);people_audit('payroll_note','Nhân viên #'.$uid,['before'=>$old,'after'=>array_intersect_key($data,array_flip(['id','user_id','month','amount','note','recurring','active']))]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}
}
function payroll_notes_due(int $uid,string $month): array {$db=payroll_run_schema();$q=$db->prepare('SELECT * FROM payroll_notes WHERE user_id=? AND active=1 AND ((recurring=0 AND month=?) OR (recurring=1 AND month<=?)) ORDER BY id');$q->execute([$uid,$month,$month]);return $q->fetchAll();}
function payroll_notes_list(string $month): array {people_require_owner();people_month($month);$db=payroll_run_schema();$q=$db->prepare('SELECT n.*,s.username,s.name FROM payroll_notes n JOIN staff s ON s.id=n.user_id WHERE n.month=? OR (n.recurring=1 AND n.month<=?) ORDER BY n.active DESC,n.user_id,n.id');$q->execute([$month,$month]);return $q->fetchAll();}
function payroll_generate(string $month,string $note='',bool $automatic=false): array {
 if(!$automatic)people_require_owner();elseif(PHP_SAPI!=='cli')throw new RuntimeException('Không được gọi tác vụ tự động từ website.',403);[$from,$to]=people_month($month);if($from>time())throw new RuntimeException('Chưa đến tháng công này.',400);if(mb_strlen($note)>2000)throw new RuntimeException('Ghi chú tối đa 2.000 ký tự.',400);$policy=payroll_policy();if(!payroll_ready($policy))throw new RuntimeException('Chưa đủ quy tắc tính lương.',409);$db=payroll_run_schema();$db->beginTransaction();
 try{if($automatic){$q=$db->prepare("SELECT * FROM payroll_runs WHERE month=? AND run_kind='automatic'");$q->execute([$month]);if($existing=$q->fetch()){$db->commit();return ['id'=>(int)$existing['id'],'already'=>true];}}
 $rows=[];$noteCount=0;$users=$db->query('SELECT id,username,name,full_name,department,group_id,birth_date,created_at,active FROM staff ORDER BY id')->fetchAll();foreach($users as $u){if(strtotime($u['created_at'])>=$to)continue;$sessions=people_effective_sessions((int)$u['id'],$from,$to);$schedule=payroll_schedule_list((int)$u['id'],$month);if(!(int)$u['active']&&!$sessions&&!$schedule)continue;$p=payroll_compute($sessions,$schedule,$month,$policy,$u['birth_date']?:null);$notes=payroll_notes_due((int)$u['id'],$month);$extra=array_sum(array_map(fn($n)=>(int)$n['amount'],$notes));$p['extra']=$extra;$p['total']+=$extra;$p['calculationNotes']=$notes;$noteCount+=count($notes);$evidence=[];foreach($sessions as $s){unset($s['activity']);$evidence[]=$s;}$rows[]=['user'=>array_intersect_key($u,array_flip(['id','username','name','full_name','department','group_id'])),'payroll'=>$p,'sessions'=>$evidence];}
 $now=gmdate('c');$payDate=payroll_pay_date($month);$actor=$automatic?'system:payroll':team_identity()['username'];$snapshot=['month'=>$month,'payDate'=>$payDate,'calculatedAt'=>$now,'policy'=>$policy,'noteCount'=>$noteCount,'rows'=>$rows];$db->prepare('INSERT INTO payroll_runs(month,snapshot,note,actor,created_at,run_kind,pay_date,note_count) VALUES(?,?,?,?,?,?,?,?)')->execute([$month,json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$note,$actor,$now,$automatic?'automatic':'manual',$payDate,$noteCount]);$id=(int)$db->lastInsertId();people_audit('payroll_calculate',$month,['id'=>$id,'payDate'=>$payDate,'employeeCount'=>count($rows),'noteCount'=>$noteCount,'note'=>$note],null,$automatic?['id'=>0,'username'=>$actor,'name'=>'Tính lương tự động ngày 20']:null);$db->commit();return ['id'=>$id,'already'=>false,'noteCount'=>$noteCount,'payDate'=>$payDate];
 }catch(Throwable $e){$db->rollBack();throw $e;}
}
function payroll_latest(string $month): ?array {people_require_owner();people_month($month);$q=payroll_run_schema()->prepare('SELECT * FROM payroll_runs WHERE month=? ORDER BY id DESC LIMIT 1');$q->execute([$month]);$r=$q->fetch();if(!$r)return null;$r['snapshot']=json_decode($r['snapshot'],true,512,JSON_THROW_ON_ERROR);return $r;}
function payroll_latest_notice(): ?array {people_require_owner();$r=payroll_run_schema()->query('SELECT id,month,pay_date,note_count FROM payroll_runs ORDER BY id DESC LIMIT 1')->fetch();return $r?:null;}
